import json
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import TYPE_CHECKING, Any, TextIO

from daft.subscribers.abc import Subscriber

if TYPE_CHECKING:
    from collections.abc import Mapping

    from daft.daft import PyMicroPartition, PyQueryMetadata, PyQueryResult, StatType


# Alias used to attach/detach the event log subscriber from the Daft context.
_EVENT_LOG_ALIAS = "_event_log"

# Holds the currently active EventLogSubscriber instance, or None if disabled.
_EVENT_LOG_SUBSCRIBER: EventLogSubscriber | None = None


def _now_ms() -> float:
    """Returns a monotonic timestamp in milliseconds, used for durations."""
    return time.monotonic() * 1000.0


def _iso_ts() -> str:
    """Returns the current wall-clock time as an ISO 8601 timestamp string."""
    return datetime.now(timezone.utc).isoformat()


class EventLogSubscriber(Subscriber):
    """A subscriber that writes query lifecycle events to JSONL log files.

    One file is written per query at ``<log_dir>/<query_id>/events.jsonl``. Each
    line is a JSON object describing a single event, with at minimum an ``event``
    name, a ``ts`` timestamp, and the ``query_id``.
    """

    def __init__(self, log_dir: str | Path) -> None:
        self.log_dir = Path(log_dir)
        self.log_dir.mkdir(parents=True, exist_ok=True)

        self._closed = False

        # Open file handles keyed by query_id.
        self._files: dict[str, TextIO] = {}

        # Timing state, in monotonic milliseconds.
        self._query_starts: dict[str, float] = {}
        self._optimization_starts: dict[str, float] = {}
        self._exec_starts: dict[str, float] = {}
        self._operator_starts: dict[tuple[str, int], float] = {}

    def _write_event(self, query_id: str, event: str, **fields: Any) -> None:
        """Writes a single event line to the query's log file."""
        f = self._files.get(query_id)
        if f is None:
            return
        record: dict[str, Any] = {"event": event, "ts": _iso_ts(), "query_id": query_id}
        record.update(fields)
        f.write(json.dumps(record) + "\n")
        f.flush()

    def on_query_start(self, query_id: str, metadata: PyQueryMetadata) -> None:
        if self._closed:
            return

        query_dir = self.log_dir / query_id
        query_dir.mkdir(parents=True, exist_ok=True)
        self._files[query_id] = (query_dir / "events.jsonl").open("w")

        self._query_starts[query_id] = _now_ms()

        self._write_event(query_id, "event_log_started")
        self._write_event(query_id, "query_started")

        unoptimized_plan = None
        try:
            unoptimized_plan = metadata.unoptimized_plan
        except AttributeError:
            unoptimized_plan = None
        self._write_event(query_id, "plan_unoptimized", plan=unoptimized_plan)

    def on_query_end(self, query_id: str, result: PyQueryResult) -> None:
        if self._closed:
            return

        start = self._query_starts.get(query_id)
        duration_ms = 0 if start is None else max(0, int(_now_ms() - start))

        status = _status_from_result(result)

        self._write_event(query_id, "query_ended", status=status, duration_ms=duration_ms)

        # Clear all timing state associated with this query only.
        self._query_starts.pop(query_id, None)
        self._optimization_starts.pop(query_id, None)
        self._exec_starts.pop(query_id, None)
        for key in [k for k in self._operator_starts if k[0] == query_id]:
            del self._operator_starts[key]

        f = self._files.pop(query_id, None)
        if f is not None:
            f.close()

    def on_result_out(self, query_id: str, result: PyMicroPartition) -> None:
        pass

    def on_optimization_start(self, query_id: str) -> None:
        if self._closed:
            return
        self._optimization_starts[query_id] = _now_ms()
        self._write_event(query_id, "optimization_started")

    def on_optimization_end(self, query_id: str, optimized_plan: str) -> None:
        if self._closed:
            return
        start = self._optimization_starts.get(query_id)
        duration_ms = None if start is None else max(0, int(_now_ms() - start))
        self._write_event(query_id, "optimization_ended", duration_ms=duration_ms, plan=optimized_plan)

    def on_exec_start(self, query_id: str, physical_plan: str) -> None:
        if self._closed:
            return
        self._exec_starts[query_id] = _now_ms()
        self._write_event(query_id, "exec_started", plan=physical_plan)

    def on_exec_operator_start(self, query_id: str, node_id: int) -> None:
        if self._closed:
            return
        self._operator_starts[(query_id, node_id)] = _now_ms()
        self._write_event(query_id, "operator_started", node_id=node_id)

    def on_exec_emit_stats(
        self, query_id: str, stats: Mapping[int, Mapping[str, tuple[StatType, Any]]]
    ) -> None:
        pass

    def on_exec_operator_end(self, query_id: str, node_id: int) -> None:
        if self._closed:
            return
        start = self._operator_starts.get((query_id, node_id))
        duration_ms = None if start is None else max(0, int(_now_ms() - start))
        self._write_event(query_id, "operator_ended", node_id=node_id, duration_ms=duration_ms)

    def on_exec_end(self, query_id: str) -> None:
        if self._closed:
            return
        start = self._exec_starts.get(query_id)
        duration_ms = None if start is None else max(0, int(_now_ms() - start))
        self._write_event(query_id, "exec_ended", duration_ms=duration_ms)

    def close(self) -> None:
        self._closed = True
        for f in self._files.values():
            try:
                f.close()
            except Exception:
                pass
        self._files.clear()


def _status_from_result(result: PyQueryResult) -> str:
    """Maps a query result's end state to a status string."""
    try:
        end_state = result.end_state
    except AttributeError:
        return "ok"

    name = getattr(end_state, "name", str(end_state))
    if name == "Finished":
        return "ok"
    if name == "Failed":
        return "failed"
    if name == "Canceled":
        return "canceled"
    if name == "Dead":
        return "failed"
    return "ok"


def enable_event_log(log_dir: str | Path | None = None) -> None:
    """Creates and attaches an :class:`EventLogSubscriber` to the Daft context.

    Args:
        log_dir: Directory under which per-query event logs are written. If None,
            a default location (``.daft/event_logs`` under the current working
            directory) is used.
    """
    global _EVENT_LOG_SUBSCRIBER

    import daft

    if log_dir is None:
        log_dir = Path.cwd() / ".daft" / "event_logs"

    subscriber = EventLogSubscriber(log_dir)

    ctx = daft.context.get_context()
    ctx.attach_subscriber(_EVENT_LOG_ALIAS, subscriber)

    _EVENT_LOG_SUBSCRIBER = subscriber


def disable_event_log() -> None:
    """Detaches and closes the active event log subscriber, if any."""
    global _EVENT_LOG_SUBSCRIBER

    import daft

    subscriber = _EVENT_LOG_SUBSCRIBER
    _EVENT_LOG_SUBSCRIBER = None

    if subscriber is not None:
        subscriber.close()

    ctx = daft.context.get_context()
    ctx.detach_subscriber(_EVENT_LOG_ALIAS)
